  "antioxidantProtection": "ஆக்ஸிஜனேற்ற எதிர்ப்புப் பாதுகாப்பு",
  "antioxidantProtectionDesc": ": ROS-ஐ நடுநிலையாக்க தினமும் பெர்ரி, கிரீன் டீ மற்றும் 85%+ டார்க் சாக்லேட் உட்கொள்ளவும்.",
  "addStillnessRoutine": "5 நிமிட அமைதி வழக்கத்தைச் சேர்க்கவும்",
  "addStillnessRoutineDesc": ": அதிகரித்த கார்டிசோலைக் குறைக்க தினமும் இருமுறை 4-7-8 ஆழ்ந்த சுவாசப் பயிற்சி செய்யுங்கள்.",
  "postMealWalking": "உணவுக்குப் பின் லேசான நடைபயிற்சி",
  "postMealWalkingDesc": ": குளுக்கோஸ் அதிகரிப்பைத் தணிக்கவும் செல்லுலார் அழுத்தத்தைக் குறைக்கவும் மதிய உணவு/இரவு உணவிற்குப் பிறகு 15 நிமிட நடைபயிற்சி மேற்கொள்ளவும்.",
  "pureWaterProtocol": "தூய நீர் நெறிமுறை",
  "pureWaterProtocolDesc": ": பூச்சிக்கொல்லிகள் & கனரக உலோகங்களை அகற்ற இரட்டை நீர் வடிகட்டுதலை (RO + செயல்படுத்தப்பட்ட கார்பன்) பயன்படுத்தவும். பிளாஸ்டிக் தண்ணீர் பாட்டில்களைத் தவிர்க்கவும்.",
  "immediateStressShield": "உடனடி மன அழுத்தப் பாதுகாப்பு (மியா AI)",
  "immediateStressShieldDesc": ": உங்கள் நரம்பு மண்டலத்தை அமைதிப்படுத்த தினமும் 4-7-8 சுவாசம் மற்றும் 5-4-3-2-1 கிரவுண்டிங் பயிற்சிகளைப் பயன்படுத்தவும்.",
  "environmentalAudit": "சுற்றுச்சூழல் தணிக்கை",
  "environmentalAuditDesc": ": பிளாஸ்டிக் குடிநீர் கொள்கலன்களைத் தவிர்க்கவும் (மைக்ரோபிளாஸ்டிக்ஸைத் தடுக்கிறது) மற்றும் RO + செயல்படுத்தப்பட்ட கார்பன் வடிகட்டலை நிறுவவும்.",
  "strictSleepHygiene": "கண்டிப்பான தூக்க சுகாதாரம்",
  "strictSleepHygieneDesc": ": படுக்கைக்குச் செல்வதற்கு 45 நிமிடங்களுக்கு முன் அனைத்து திரைகளையும் அணைத்துவிட்டு, குளிர்ந்த, இருண்ட அறையில் தூங்கவும்.",
