  "founderMessageTitle": "எங்கள் நிறுவனர்களின் செய்தி",
  "founderPara1": "{appName} க்கு வரவேற்கிறோம். சர்க்காடியன் உயிரியல், ஸ்மார்ட் ஊட்டச்சத்து மற்றும் தொடர்ச்சியான குளுக்கோஸ் கண்காணிப்பு ஆகியவற்றின் மூலம் நாள்பட்ட வாழ்க்கை முறை பிரச்சினைகளை இயற்கையாக குணப்படுத்தும் நோக்கத்துடன் எங்கள் தளம் உருவானது.",
  "founderPara2": "ஆதாரம் சார்ந்த வாழ்க்கை முறை நெறிமுறைகள், தனிப்பயனாக்கப்பட்ட உணவு ஸ்பைக் மதிப்பீடுகள் மற்றும் நிகழ்நேர மருத்துவ வழிகாட்டுதல் உங்கள் விரல் நுனியில் இருக்கும் வகையில் நாங்கள் இந்த தளத்தை உருவாக்கியுள்ளோம். உங்கள் ஆரோக்கிய பயணம் தனித்துவமானது; நீங்கள் நோயற்ற, சுறுசுறுப்பான வாழ்க்கை வாழ உதவுவதே எங்கள் முதன்மை இலக்கு.",
  "founderPara3": "எங்கள் தளம் மீது நம்பிக்கை வைத்து இந்த தடுப்பு ஆரோக்கிய இயக்கத்தில் இணைந்ததற்கு மனமார்ந்த நன்றிகள்.",
