  "developerNote": "மென்பொருள் பொறியாளர் குறிப்பு",
  "behindEngineeringTitle": "பொறியியல் & AI தளத்தின் பின்னணி",
  "developerPara1": "{appName} தளத்தை உருவாக்குவது பொறியியல் ஆர்வம், தொழில்நுட்ப துல்லியம் மற்றும் அக்கறையின் அசாதாரண பயணமாகும். தொடர்ச்சியான குளுக்கோஸ் சென்சார் ஒருங்கிணைப்பு மற்றும் தானியங்கி உணவு ஸ்பைக் அல்காரிதம்கள் முதல் எளிய மருத்துவ ஆலோசனை செயல்முறைகள் வரை அனைத்தும் உள்ளுணர்வுடன், வேகமாகவும் உதவும் வகையில் வடிவமைக்கப்பட்டுள்ளன.",
  "developerPara2": "எங்கள் மென்பொருள் பயனர்கள் தங்கள் ஆரோக்கியத்தைக் கண்காணிக்கவும், குளுக்கோஸ் உயர்வைத் தவிர்க்கவும், ஆரோக்கியமான பழக்கவழக்கங்களை உருவாக்கவும் உதவுகிறது என்பதை அறிவது எங்கள் பணிக்கு அர்த்தமளிக்கிறது. அதிகபட்ச பாதுகாப்பு, வேகம் மற்றும் பதிலளிப்பை உறுதிசெய்ய கட்டமைப்பைத் தொடர்ந்து மேம்படுத்துகிறோம்.",
  "developerPara3": "உங்களுக்கு ஏதேனும் பரிந்துரைகள் இருந்தால், பிழையைக் கண்டறிந்தால், அல்லது புதிய அம்சத்தை விரும்பினால், தயவுசெய்து மதிப்பாய்வு & கருத்து தெரிவிக்கவும். நாங்கள் ஒவ்வொரு குறிப்பையும் கவனமாக படிக்கிறோம்!",
