  "tourWelcomeTitle": "{appName} க்கு வரவேற்கிறோம்!",
  "tourWelcomeDesc": "உங்கள் பிரீமியம் {appTagline}. குளுக்கோஸ் உயர்வை கண்காணிக்கவும், உணவுகளை பதிவு செய்யவும் மற்றும் உகந்த வளர்சிதை மாற்ற ஆரோக்கியத்திற்கான அறிவார்ந்த மருத்துவ பரிந்துரைகளைப் பெறவும் உதவுகிறோம்.",
