  "tourCgmDesc": "உங்கள் Abbott CGM CSV அல்லது PDF அறிக்கைகளைப் பதிவேற்றவும். எங்கள் அல்காரிதம்கள் உடனடியாக உங்கள் தரவை டிஜிட்டல் மயமாக்கி விரிவான வரைபடங்களை உருவாக்குகின்றன.",
