  "tourFoodDesc": "உங்கள் உணவுகளைக் கண்காணிக்கவும், விரிவான உணவுப் பட்டியலில் தேடவும். குறிப்பிட்ட உணவுகள் உங்கள் குளுக்கோஸ் அளவை எவ்வாறு பாதிக்கின்றன என்பதைக் கண்டறியவும்.",
  "tourAiTitle": "AI ஆரோக்கிய பயிற்சியாளர்",
  "tourAiDesc": "தனிப்பயனாக்கப்பட்ட கருத்துகளுக்கு எங்கள் ஒருங்கிணைந்த AI பயிற்சியாளருடன் கலந்துரையாடுங்கள். உங்கள் ஆரோக்கிய இலக்குகளுக்கு ஏற்ற ஆலோசனைகளைப் பெறுங்கள்.",
