    "card1Title": "மூக்கு சுவாசம் & நைட்ரிக் ஆக்சைடு (NO)",
    "card1Desc": "உங்கள் சைனஸ்கள் தொடர்ந்து நைட்ரிக் ஆக்சைடு வாயுவை உருவாக்குகின்றன. மூக்கின் வழியே சுவாசிப்பது NO-வை கீழ் நுரையீரலுக்கு எடுத்துச்சென்று நுண்குழாய்களை விரிவடையச் செய்து இரத்த ஆக்சிஜன் அளவை 10–18% வரை அதிகரிக்கிறது.",
