  "gia.optWhatIsLynch": "லிஞ்ச் நோய்க்குறி என்றால் என்ன?",
  "gia.optBookCounseling": "மரபணு ஆலோசனையை முன்பதிவு செய்",
  "gia.qCancerTypes": "நன்றி. தலைமுறைகளுக்கிடையேயான புற்றுநோய் வகைகளைப் புரிந்துகொள்வது வழிகாட்டுதல் மதிப்பீடுகளுக்கு முக்கியமானது.\n\nஉங்களுக்கோ அல்லது உங்கள் குடும்பத்தினருக்கோ எந்த வகையான புற்றுநோய் கண்டறியப்பட்டது?",
  "gia.qAge": "நன்றி. கண்டறியப்பட்ட வயது மரபணு ஆபத்தின் மிக முக்கியமான குறிகாட்டியாகும்.\n\nபுற்றுநோய் முதன்முதலில் எந்த வயதில் கண்டறியப்பட்டது?",
  "gia.qRelatives": "புரிந்தது. அடுத்து, எந்த குறிப்பிட்ட உறவினர்கள் பாதிக்கப்பட்டனர், மற்றும் குடும்பத்தின் எந்தப் பக்கத்தில் (தாய்வழி அல்லது தந்தைவழி)?",
  "gia.qAncestry": "புரிந்தது. குடும்பத்தில் ஏதேனும் மரபணு சோதனை முடிவுகள் உள்ளதா (எ.கா. BRCA1/2 பாசிட்டிவ்)?",
  "gia.assessmentSummary": "### 🧬 NCCN v2.2025 புற்றுநோய் மரபணு ஆபத்து மதிப்பீடு\n\nபகிர்ந்த வரலாற்றின் அடிப்படையில், தற்போதைய NCCN வழிகாட்டுதல்களின்படி **மரபணு புற்றுநோய் பரிசோதனை பரிந்துரைக்கப்படுகிறது**.\n\n**பரிசீலிக்க வேண்டிய மரபணு பேனல்கள்:**\n- **HBOC பேனல் (BRCA1, BRCA2, PALB2, ATM, CHEK2)**\n- **லிஞ்ச் நோய்க்குறி பேனல் (MLH1, MSH2, MSH6, PMS2, EPCAM)**\n\n**அடுத்த படிகள்:**\n1. சான்றளிக்கப்பட்ட மரபணு ஆலோசகரை அணுகவும்.\n2. பல மரபணு பேனல் ரத்தப் பரிசோதனை செய்யவும்.",
  "closeChatAria": "அரட்டையை மூடு",
  "gia.assessmentNextStepsDesc": "மரபணு ஆலோசகர் உங்கள் குடும்ப வரலாற்றை ஆய்வு செய்து, துல்லியமான மரபணு பரிசோதனையை பரிந்துரைப்பார்.",
