  "testName.cea": "S. CEA",
  "testName.psa": "S. PSA",
  "testFreq.monthly": "மாதாந்திரம்",
  "testFreq.papSmearUnder40": "ஒவ்வொரு 3 வருடங்களுக்கும், 21 வயதிலிருந்து",
  "testFreq.hpvVaccine": "ஏற்கனவே போடப்படவில்லை என்றால் ஒருமுறை தடுப்பூசி வரிசை",
  "testFreq.yearly": "வருடாந்திரம்",
  "testFreq.papSmearOver40": "ஒவ்வொரு 3 வருடங்களுக்கும் (அல்லது மகளிர் மருத்துவ நிபுணர் ஆலோசனைப்படி 5 ஆண்டுகளுக்கு ஒருமுறை)",
  "testFreq.ca125": "வருடாந்திரம் (துணைப் பரிசோதனையாக)",
  "testFreq.oralCancer": "வருடாந்திரம், அல்லது புண்கள் தென்பட்டால் உடனடியாக",
  "testFreq.adjunct": "வருடாந்திரம் (துணைப் பரிசோதனையாக)",
  "testNote.breastSelfExam": "ஒவ்வொரு மாதவிடாய் சுழற்சியிலும் உங்கள் மார்பகங்களின் இயல்பான தோற்றத்தை அறிந்து கொள்ளுங்கள். ஏதேனும் கட்டி, தோல் மாற்றம் அல்லது கசிவு தென்பட்டால் உடனே தெரிவிக்கவும்.",
  "testNote.breastSelfExamOver40": "மேலே உள்ளவாறு — மருத்துவ பரிசோதனை மற்றும் மேமோகிராமோடு இணைந்து தொடரவும்.",
  "testNote.papSmear": "கர்ப்பப்பை வாய் புற்றுநோய் முந்தைய நிலையை கண்டறிய உதவுகிறது.",
  "testNote.papSmearOver40": "சுமார் 65 வயது வரை அல்லது மருத்துவர் ஆலோசனைப்படி தொடரவும்.",
  "testNote.hpvVaccine": "முதலிலேயே போட்டுக் கொள்வது மிகவும் பயனுள்ளது; பிறகும் போட்டுக்கொள்வது மதிப்புடையது — மகளிர் மருத்துவரிடம் ஆலோசனை பெறவும்.",
  "testNote.mammogram": "ஆரம்ப நிலையிலேயே கண்டறிவதற்கான டிஜிட்டல் மேமோகிராபி.",
  "testNote.ca125": "கருப்பை புற்றுநோய் அபாய விழிப்புணர்விற்கு.",
  "testNote.ldct": "நுரையீரல் புற்றுநோயை ஆரம்பத்தில் கண்டறிய உதவுகிறது.",
  "testNote.oralCancer": "வாய் மற்றும் தொண்டையின் நேரடி பரிசோதனை — புகையிலை பயன்படுத்துபவர்களுக்கு மிகவும் அவசியம்.",
  "testNote.cea": "கார்சினோஎம்ப்ரியானிக் ஆன்டிஜென், பொதுவான கட்டி குறிப்பான் பரிசோதனையாகப் பயன்படுத்தப்படுகிறது.",
  "testNote.psa": "புரோஸ்டேட்-குறிப்பிட்ட ஆன்டிஜென், புரோஸ்டேட் புற்றுநோய் அபாய விழிப்புணர்விற்கு.",
  "testEvidence.breastSelfExam": "இந்தியாவில் பெரும்பாலான மார்பக புற்றுநோய்கள் தாமதமாகவே கண்டறியப்படுவதால், குறைந்த செலவில் விழிப்புணர்வுக்கான சிறந்த பழக்கமாக இது பரிந்துரைக்கப்படுகிறது.",
  "testEvidence.ca125": "குடும்ப வரலாறு உள்ள பெண்களுக்கு அல்லது அல்ட்ராசவுண்டோடு சேர்த்து இது மிகவும் பயனுள்ளதாக இருக்கும்.",
  "testEvidence.ldct": "அதிகமாக புகைப்பிடித்தவர்கள் மற்றும் அதிக அபாயத்தில் உள்ளவர்களுக்கு வருடாந்திர LDCT பரிந்துரைக்கப்படுகிறது.",
  "testEvidence.cea": "இது முக்கியமாக புற்றுநோய் கண்காணிப்பிற்கு பயன்படுத்தப்படும் துணை சோதனையாகும்.",
  "testEvidence.psa": "புரோஸ்டேட் பரிசோதனை முடிவுகளை மருத்துவரிடம் கலந்து ஆலோசித்து முடிவு செய்வது நல்லது.",
  "testVideo.nhsBreast": "NHS — மார்பகத்தை எவ்வாறு சுய பரிசோதனை செய்வது",
  "symptom.mouthUlcer": "குணமாகாத வாய் புண், அல்லது வாயின் உள்ளே வெள்ளை/சிவப்பு திட்டு",
  "symptom.hoarseness": "தொடர்ச்சியான குரல் கம்மல் அல்லது இருமல்",
  "symptom.lump": "மார்பகம், கழுத்து அல்லது உடலில் எங்கும் ஒரு புதிய கட்டி அல்லது தடிப்பு",
  "symptom.bleeding": "மாதவிடாய்களுக்கு இடையே, மாதவிடாய் நின்ற பிறகு அசாதாரண இரத்தப்போக்கு அல்லது சிறுநீரில் இரத்தம்",
  "symptom.bloodStools": "மலத்தில் இரத்தம் அல்லது கருப்பு நிற மலம்",
  "symptom.stoolRoutine": "மலம் கழிக்கும் வழக்கத்தில் தொடர்ச்சியான மாற்றம் (மலச்சிக்கல், வயிற்றுப்போக்கு)",
  "symptom.bladder": "சிறுநீர் கழிக்கும் பழக்கவழக்கங்களில் மாற்றம்",
  "symptom.swallowing": "விழுங்குவதில் சிரமம் அல்லது தொடர்ச்சியான அஜீரணம்/அமிலத்தன்மை",
