  "disclaimer.medicalDisclaimer": "மருத்துவ மறுப்புரை",
  "disclaimer.understandAndAccept": "நான் புரிந்து கொண்டு ஏற்கிறேன்",
  "disclaimer.cancerTreatmentText": "வாழ்வியல் வழிகாட்டுதல் மற்றும் சட்ட மறுப்புரை\nஇந்த பயன்பாட்டில் உள்ள பரிந்துரைகள் கல்வி மற்றும் பொதுவான நல்வாழ்வு நோக்கங்களுக்காக மட்டுமே வழங்கப்படுகின்றன. அவை உங்கள் மருத்துவ நிபுணர்களால் வழங்கப்படும் ஆலோசனை, நோயறிதல் அல்லது சிகிச்சையை மாற்றியமைக்க அல்ல, மாறாக அவற்றுக்குத் துணையாக இருக்க வடிவமைக்கப்பட்டுள்ளன.\n\nபரிந்துரைக்கப்பட்ட ஆரோக்கியமான வாழ்க்கை முறை பழக்கங்கள்\nமருத்துவ ரீதியாக அனுமதிக்கப்படும் போது, நீங்கள் பின்வருவனவற்றைப் பின்பற்ற பரிந்துரைக்கப்படுகிறீர்கள்:\n• உங்கள் மாலை உணவை இரவு 7:00 மணிக்குள் முடித்து, உங்கள் சிகிச்சை மருத்துவரால் அங்கீகரிக்கப்பட்டால், நிலையான இரவு நேர உண்ணாவிரதக் காலத்தை (நேரக் கட்டுப்பாடு கொண்ட உணவுமுறை) பராமரிக்கவும்.\n• நடைபயிற்சி, யோகா, நீட்சி அல்லது பிற பொருத்தமான உடற்பயிற்சிகள் போன்ற உடல் இயக்கங்களில் தினமும் குறைந்தது 20 நிமிடங்கள் ஈடுபடவும்.\n• மன அழுத்தத்தைக் குறைக்க உதவும் வகையில், வாசிப்பது, இசை கேட்பது அல்லது அமைதியாக இருப்பது போன்ற நீங்கள் விரும்பும் ஒரு செயலில் தினமும் குறைந்தது 20 நிமிடங்கள் செலவிடவும்.\n• அமைதியான உறக்கத்திற்கு முன்னுரிமை அளித்து, குணமடைவதை ஊக்குவிக்கும் தளர்வு பயிற்சிகளைப் பின்பற்றவும்.\n\nமுக்கிய பாதுகாப்பு அறிவிப்பு\nஉங்கள் உணவுமுறை, உடற்பயிற்சி அல்லது அன்றாட வழக்கத்தில் ஏதேனும் குறிப்பிடத்தக்க மாற்றங்களைச் செய்வதற்கு முன், குறிப்பாக புற்றுநோய் சிகிச்சையில் இருக்கும்போது, உங்கள் முதன்மை மருத்துவர் அல்லது புற்றுநோய் நிபுணருடன் எப்போதும் கலந்தாலோசிக்கவும்.\n\nபுதிய அல்லது கடுமையான அறிகுறிகளை உணர்ந்தால் உடனடியாக அவசர மருத்துவ உதவியை நாடவும்.",
  "disclaimer.cancerSecondaryText": "வாழ்வியல் வழிகாட்டுதல் மற்றும் சட்ட மறுப்புரை\nஇந்த பயன்பாட்டில் உள்ள பரிந்துரைகள் கல்வி மற்றும் பொதுவான நல்வாழ்வு நோக்கங்களுக்காக மட்டுமே வழங்கப்படுகின்றன. அவை மருத்துவரின் ஆலோசனையை மாற்றியமைக்க அல்ல.\n\nபரிந்துரைக்கப்பட்ட வாழ்க்கை முறை பழக்கங்கள்:\n• மாலை 7:00 மணிக்குள் உணவை முடிக்கவும்.\n• தினமும் குறைந்தது 20 நிமிடங்கள் உடற்பயிற்சி செய்யவும்.\n• மன அழுத்தத்தைக் குறைக்கும் செயல்களில் ஈடுபடவும்.\n• வழக்கமான புற்றுநோய் பரிசோதனைகளை மேற்கொள்ளவும்.",
  "disclaimer.cancerPreventionText": "வாழ்வியல் வழிகாட்டுதல் மற்றும் சட்ட மறுப்புரை\nஇந்த பரிந்துரைகள் நல்வாழ்வுக்கானவை. மருத்துவ ஆலோசனைக்கு மாற்றாகாது.\n\nஆரோக்கியமான பழக்கங்கள்:\n• மாலை 7:00 மணிக்குள் உணவை முடிக்கவும்.\n• தினமும் குறைந்தது 20 நிமிடங்கள் உடற்பயிற்சி செய்யவும்.\n• நச்சுத்தன்மையற்ற சமையலறை மற்றும் தூய நீர் பழக்கங்களைப் பின்பற்றவும்.\n• 7-9 மணிநேரம் நிம்மதியான உறக்கம் கொள்ளவும்.",
  "disclaimer.generalLifestyleText": "வாழ்வியல் வழிகாட்டுதல் மற்றும் சட்ட மறுப்புரை\nஇந்த பயன்பாட்டின் பரிந்துரைகள் கல்வி நோக்கங்களுக்காக மட்டுமே.\n\nஆரோக்கியமான பழக்கங்கள்:\n• மாலை 7:00 மணிக்குள் உணவை முடிக்கவும்.\n• தினமும் 20 நிமிடங்கள் உடற்பயிற்சி செய்யவும்.\n• தியானம் மற்றும் மூச்சுப்பயிற்சி மூலம் மன அழுத்தத்தைக் குறைக்கவும்.\n• ஒவ்வொரு இரவும் 7-9 மணிநேர உறக்கம் பெறவும்.",
  "habits.hoursWord": "மணி",
