  "habits.sleepLogFailed": "உறக்கத்தைப் பதிவு செய்வதில் தோல்வி. மீண்டும் முயற்சிக்கவும்.",
  "habits.sleepDeprivationDesc": "ஆழ்ந்த உறக்கம் மூளையைச் சுத்தப்படுத்தவும் செல்களைப் புதுப்பிக்கவும் மிகவும் அவசியமானது. 6 மணி நேரத்திற்கும் குறைவான உறக்கம் இன்சுலின் எதிர்ப்பை அதிகரிக்கிறது.",
