  "mitoProgress.breakdownTitle": "மைட்டோ முன்னேற்ற விவரம்",
  "mitoProgress.disclaimerDesc": "மைட்டோ முன்னேற்றம் என்பது ஒரு வழிமுறை நல்வாழ்வு குறிகாட்டியாகும், இது முறையான மருத்துவ நோயறிதல் அல்ல.",
  "mitoProgress.metricCGM": "CGM குளுக்கோஸ் நிலைத்தன்மை",
  "mitoProgress.metricDoctor": "மருத்துவர் ஆலோசனைகள்",
  "mitoProgress.metricEnv": "சுற்றுச்சூழல் நச்சு பாதுகாப்பு",
  "mitoProgress.metricGenetics": "மரபணு இடர் விழிப்புணர்வு",
  "mitoProgress.metricHabits": "தினசரி வாழ்க்கை முறை பழக்கங்கள்",
  "mitoProgress.metricRecovery": "ஓய்வு & செல்லுலார் மீட்பு",
  "mitoProgress.metricSymptom": "அறிகுறி கண்காணிப்பு",
  "mitoProgress.tipCGMActive": "செயலில் உள்ள CGM கண்காணிப்பு நிகழ்நேர குளுக்கோஸ் தரவை வழங்குகிறது",
  "mitoProgress.tipDoctorDone": "மருத்துவ நிபுணருடன் ஆலோசனைகள் முடிக்கப்பட்டன",
  "mitoProgress.tipEnvDone": "வீடு & சமையலறை நச்சு தணிக்கை முடிந்தது",
  "mitoProgress.tipEnvTodo": "மீட்பைப் பாதுகாக்க காற்று, நீர் மற்றும் சமையலறை பிளாஸ்டிக்குகளைத் தணிக்கை செய்யுங்கள்",
  "mitoProgress.tipGeneticsDone": "பரம்பரை இடர் விவரக்குறிப்பு மதிப்பிடப்பட்டது",
  "mitoProgress.tipGeneticsTodo": "தனிப்பயனாக்கப்பட்ட தடுப்புக்காக மரபணு காரணிகளை மதிப்பாய்வு செய்யவும்",
  "mitoProgress.tipHabitsDone": "தினசரி உடற்பயிற்சி, விரதம் & ஊட்டச்சத்து பதிவு செய்யப்பட்டது",
  "mitoProgress.tipHabitsTodo": "மதிப்பெண்ணை அதிகரிக்க விரதம், உடற்பயிற்சி மற்றும் தூக்கத்தை பதிவு செய்யவும்",
  "mitoProgress.tipRecoveryDone": "சிறந்த ஓய்வு & விழிப்புணர்வு பதிவு செய்யப்பட்டது",
  "mitoProgress.tipRecoveryTodo": "7+ மணிநேர ஆழ்ந்த தூக்கம் மற்றும் மன அழுத்தத்தைக் குறைக்கும் பயிற்சிக்கு முன்னுரிமை அளியுங்கள்",
  "mitoProgress.tipSymptomDone": "தினசரி அறிகுறிகள் மற்றும் முக்கிய அளவீடுகள் புதுப்பிக்கப்பட்டன",
  "mitoProgress.tipSymptomTodo": "ஆரம்பகால மருத்துவக் கண்டறிதலுக்காக ஏதேனும் அசௌகரியம் அல்லது அளவீடுகளை பதிவு செய்யவும்",
  "mitoProgress.title": "மைட்டோ சுகாதாரக் குறியீடு",
  "mitoProgress.wellnessIndicator": "முழுமையான சுகாதார மதிப்பெண்",
  "notif.customizeMatrixDesc": "ஒவ்வொரு அறிவிப்பு வகைக்கும் எந்தெந்த வழிகளில் (Push, In-App, Email) பெற விரும்புகிறீர்கள் என்பதைத் தனிப்பயனாக்கவும்.",
