  "notif.manageAlertsDesc": "நினைவூட்டல்கள் மற்றும் சுகாதார அறிவிப்புகளை எவ்வாறு மற்றும் எப்போது பெறுவது என்பதை நிர்வகிக்கவும்.",
  "notif.preferencesTitle": "அறிவிப்பு விருப்பத்தேர்வுகள்",
