  "insight.walkingAfterMeals": "முக்கிய உணவுக்குப் பிறகு 10-15 நிமிடங்கள் நடைப்பயிற்சி செய்வது இரத்தத்தில் உள்ள குளுக்கோஸை விரைவாக எரிக்க உதவுகிறது. வெள்ளை அரிசிக்கு பதிலாக சிறுதானியங்களை பயன்படுத்த முயற்சிக்கவும்.",
  "insight.stayingHydrated": "போதுமான நீர் குடிப்பது மிகவும் அவசியம்! உணவுக்கு முன் தண்ணீர் குடிப்பது இரத்த சர்க்கரை உயர்வை குறைத்து வளர்சிதை மாற்றத்தை ஆதரிக்கிறது.",
  "insight.pairCarbsWithProtein": "கார்போஹைட்ரேட்டுகளுடன் ஆரோக்கியமான கொழுப்புகள் அல்லது புரதங்களை (கொட்டைகள், வெண்ணெய் பழம் அல்லது முட்டை போன்றவை) சேர்த்து உட்கொள்வது செரிமானத்தை மெதுவாக்கி சர்க்கரை உயர்வைத் தடுக்கும்.",
  "insight.qualitySleepInsulin": "இரவில் 7-8 மணிநேரம் ஆழ்ந்து தூங்குவது இன்சுலின் உணர்திறனை மேம்படுத்தி காலை நேர சர்க்கரை அளவை சீராக வைக்க உதவுகிறது.",
  "insight.stressCortisolGlucose": "அதிக மன அழுத்தம் கார்டிசோலை வெளியிட்டு உணவு இல்லாமலேயே சர்க்கரை அளவை உயர்த்தும். மன அழுத்தம் ஏற்படும் போது 5 நிமிடங்கள் ஆழமான சுவாசப் பயிற்சி செய்யுங்கள்.",
  "insight.eatMealsInOrder": "உணவை இந்த வரிசையில் சாப்பிட முயற்சிக்கவும்: முதலில் காய்கறிகள், பின் புரதம் மற்றும் கொழுப்புகள், இறுதியாக கார்போஹைட்ரேட்டுகள். இது சர்க்கரை உயர்வை பெருமளவில் குறைக்கும்.",
