  "cancerDesc.Lip, oral cavity": "புகையிலை மெல்லுதல் மற்றும் புகைபிடித்தல் காரணமாக இந்தியாவில் உதடு மற்றும் வாய்க்குழி புற்றுநோய்கள் அதிக அளவில் காணப்படுகின்றன.",
  "cancerDesc.Lung": "புகைபிடித்தல் மற்றும் அதிகரித்து வரும் காற்று மாசுபாட்டின் காரணமாக நுரையீரல் புற்றுநோய் ஒரு முக்கிய இறப்புக் காரணியாக உள்ளது.",
  "cancerDesc.Colorectum": "நவீன வாழ்க்கை முறை மாற்றங்கள், பதப்படுத்தப்பட்ட உணவுகள் மற்றும் உடற்பயிற்சியின்மை காரணமாக பெருங்குடல் புற்றுநோய்கள் வேகமாக அதிகரித்து வருகின்றன.",
  "cancerDesc.Stomach": "அதிக உப்பு உட்கொள்ளல் மற்றும் ஹெச். பைலோரி பாக்டீரியா தொற்று போன்ற உணவுப் பழக்கவழக்கங்களுடன் தொடர்புடைய வயிற்றுப் புற்றுநோய் இந்தியாவில் பரவலாகக் காணப்படுகிறது.",
  "cancerDesc.Prostate": "புரோஸ்டேட் புற்றுநோய் வயதுக்கு ஏற்ப அதிகரிக்கிறது, அதிக ஆபத்துள்ள நபர்களுக்கு ஆரம்பகால பரிசோதனை பரிந்துரைக்கப்படுகிறது.",
  "cancerDesc.Other cancers": "மற்ற பல்வேறு புற்றுநோய்களின் கூட்டுப் பங்கு ஆகும், ஒவ்வொன்றும் மொத்த எண்ணிக்கையில் சிறிய பங்கை வகிக்கின்றன.",
  "cancerDesc.Breast": "இந்தியப் பெண்களிடையே மார்பகப் புற்றுநோய் மிகவும் பொதுவான ஒன்றாக உள்ளது, நகர்ப்புறங்களில் இது மிக வேகமாக அதிகரித்து வருகிறது.",
  "cancerDesc.Cervix uteri": "கருப்பை வாய் புற்றுநோயை சரியான நேரத்தில் HPV தடுப்பூசி மற்றும் வழக்கமான பரிசோதனை (பேப் ஸ்மியர்) மூலம் முழுமையாகத் தடுக்க முடியும்.",
  "cancerDesc.Ovary": "சினைப்பை புற்றுநோய்கள் பெரும்பாலும் பிந்தைய கட்டங்களிலேயே கண்டறியப்படுகின்றன, எனவே தொடர்ந்து இருக்கும் வயிற்று அசௌகரியங்களை உடனடியாக பரிசோதிக்க வேண்டும்.",
  "protocols.eyes": "கண்கள்",
  "protocols.dental": "பற்கள் & வாய்",
  "protocols.bone": "எலும்பு & எலும்புக்கூடு",
  "protocols.cardiac": "இதயம் & வாஸ்குலர்",
